const input = $input.first().json;

// Sanitize sessionId to prevent injection
const rawSessionId = (input.sessionId || input.session_id || 'default').toString();
const sessionId = rawSessionId.replace(/[^a-zA-Z0-9_-]/g, '') || 'default';

// Guard against oversized/malicious input
const maxQuestionLength = 500;
let question = (input.chatInput || input.question || input.message || '').toString().trim();
if (question.length > maxQuestionLength) {
  question = question.slice(0, maxQuestionLength);
}

// ================= CONFIG — edit these =================
const config = {
  interpModel: 'claude-haiku-4-5',      // Already using this
  synthModel:  'claude-haiku-4-5',      // ← Change from sonnet-4-6 to haiku-4-5
  maxTokensInterp: 400,                  // Reduced from 600
  maxTokensSynth:  500,                  // Reduced from 800
  // ... rest of config
};
// ======================================================

const staticData = $getWorkflowStaticData('global');
staticData.memory = staticData.memory || {};
const history = staticData.memory[sessionId] || [];
const nowISO = new Date().toISOString().slice(0,10);   // today's date, for resolving relative time

return [{ json: { sessionId, question, config, history, nowISO } }];

const resp = $input.first().json;
const carried = $('2. Build Interpretation Request').first().json;
let text = '';
try { text = (resp.content || []).map(b => b.text || '').join(''); } catch (e) {}
let intent;
try { const m = text.match(/\{[\s\S]*\}/); intent = JSON.parse(m ? m[0] : text); }
catch (e) { 
  intent = { 
    type:'aggregation', 
    operation:'count', 
    metric:'reports', 
    groupBy:'subcounty', 
    filters:[], 
    order:'desc', 
    limit:10, 
    mathRequired:true 
  }; 
}

intent.filters = Array.isArray(intent.filters) ? intent.filters.filter(f => f && f.field) : [];
intent.metric = intent.metric || 'reports';
intent.operation = intent.operation || 'count';
intent.order = intent.order || 'desc';
intent.limit = intent.limit || 10;
intent.mathRequired = intent.mathRequired !== false;
if (Array.isArray(intent.subcounties)) intent.filters = intent.filters.concat(intent.subcounties.map(s => ({field:'subcounty', value:s})));

// ================= SHEET DETECTION =================
function detectSheet(question) {
  const q = question.toLowerCase();

  // Use explicit programme terms first. Generic terms such as attendees and
  // partners remain available on both datasets, so they must not force a sheet.
  const sensKeywords = [
    'public sensitization', 'public sensitisation', 'sensitization programme',
    'sensitisation programme', 'community sensitization', 'community sensitisation',
    'sensitization activity', 'sensitisation activity', 'sensitize', 'sensitise',
    'awareness campaign', 'awareness activity', 'public baraza', 'key message',
    'sensitatization'
  ];

  for (const kw of sensKeywords) {
    if (q.includes(kw)) {
      console.log('Detected Sensitization Programme sheet');
      return 'Sensitization Programme';
    }
  }

  // Check for Greening Initiative keywords
  const greenKeywords = [
    'tree', 'plant', 'greening', 'cleanup', 'clean up',
    'staff', 'resources', 'deployed', 'seedlings'
  ];

  for (const kw of greenKeywords) {
    if (q.includes(kw)) {
      console.log('Detected Greening Initiative sheet');
      return 'Greening Initiative';
    }
  }

  // Default
  console.log('Defaulting to Greening Initiative sheet');
  return 'Greening Initiative';
}

// ================= DETERMINE SHEET =================
const detectedSheet = detectSheet(carried.question);

// Set the sheet in the intent
intent.sheet = detectedSheet;

// ================= DATE RESOLUTION =================
const nowISO = carried.nowISO || new Date().toISOString().slice(0,10);
function isod(dt){ return dt.toISOString().slice(0,10); }
function mk(Y,M,D){ return new Date(Date.UTC(Y,M,D)); }
function resolvePeriod(period, ref){
  const now=new Date(ref+'T00:00:00Z'); const y=now.getUTCFullYear(), m=now.getUTCMonth(), d=now.getUTCDate();
  const sow=dt=>{ const day=(dt.getUTCDay()+6)%7; const s=new Date(dt); s.setUTCDate(dt.getUTCDate()-day); return s; };
  switch(String(period||'').toLowerCase()){
    case 'today': return {from:ref,to:ref,label:'today'};
    case 'yesterday': { const t=mk(y,m,d-1); return {from:isod(t),to:isod(t),label:'yesterday'}; }
    case 'this_week': return {from:isod(sow(now)),to:ref,label:'this week'};
    case 'last_week': { const s=sow(now); const ls=new Date(s); ls.setUTCDate(s.getUTCDate()-7); const le=new Date(s); le.setUTCDate(s.getUTCDate()-1); return {from:isod(ls),to:isod(le),label:'last week'}; }
    case 'this_month': return {from:isod(mk(y,m,1)),to:ref,label:'this month'};
    case 'last_month': return {from:isod(mk(y,m-1,1)),to:isod(mk(y,m,0)),label:'last month'};
    case 'last_7_days': return {from:isod(mk(y,m,d-6)),to:ref,label:'the last 7 days'};
    case 'last_30_days': return {from:isod(mk(y,m,d-29)),to:ref,label:'the last 30 days'};
    case 'last_90_days': return {from:isod(mk(y,m,d-89)),to:ref,label:'the last 90 days'};
    case 'this_quarter': { const q=Math.floor(m/3); return {from:isod(mk(y,q*3,1)),to:ref,label:'this quarter'}; }
    case 'last_quarter': { let q=Math.floor(m/3)-1, yy=y; if(q<0){q=3;yy--;} return {from:isod(mk(yy,q*3,1)),to:isod(mk(yy,q*3+3,0)),label:'last quarter'}; }
    case 'this_year': return {from:isod(mk(y,0,1)),to:ref,label:'this year'};
    case 'ytd': return {from:isod(mk(y,0,1)),to:ref,label:'year to date'};
    case 'last_year': return {from:isod(mk(y-1,0,1)),to:isod(mk(y-1,11,31)),label:'last year'};
    default: return null;
  }
}
function prettyRange(from,to){
  const M=['January','February','March','April','May','June','July','August','September','October','November','December'];
  if(!from&&!to) return 'all dates';
  if(from&&to){
    const [fy,fm,fd]=from.split('-').map(Number), [ty,tm,td]=to.split('-').map(Number);
    if(from===to) return from;
    if(fd===1&&fy===ty&&fm===tm){ const last=new Date(Date.UTC(ty,tm,0)).getUTCDate(); if(td===last) return M[fm-1]+' '+fy; }
    if(fm===1&&fd===1&&tm===12&&td===31&&fy===ty) return String(fy);
    return from+' to '+to;
  }
  return from ? ('since '+from) : ('up to '+to);
}
if (!intent.dateFrom && !intent.dateTo && intent.period && intent.period!=='all'){
  const p=resolvePeriod(intent.period, nowISO);
  if(p){ intent.dateFrom=p.from; intent.dateTo=p.to; intent.periodLabel=p.label; }
}
if (!intent.periodLabel) intent.periodLabel = prettyRange(intent.dateFrom, intent.dateTo);

// ================= LOGGING =================
console.log('Detected Sheet:', detectedSheet);
console.log('Intent:', JSON.stringify(intent, null, 2));

return [{ 
  json: { 
    sessionId: carried.sessionId, 
    question: carried.question, 
    config: carried.config, 
    history: carried.history, 
    nowISO, 
    intent,
    detectedSheet: detectedSheet
  } 
}];

const base = $('4. Parse Intent').first().json;
const config = base.config;

function num(v){ if(v==null||v==='')return null; const m=String(v).match(/-?\d+(?:\.\d+)?/); if(!m)return null; const n=Number(m[0]); return isNaN(n)?null:n; }
const CLAMP = { staff_deployed:2000, trees_planted:100000, attendees:10000 };
function cl(field,v){ if(v==null)return null; const mx=CLAMP[field]; if(mx!=null&&(v<0||v>mx))return null; return v; }
function goodYear(s){ if(!s)return null; const y=+s.slice(0,4); return (y>=2023&&y<=2032)?s:null; }
function iso(v){ if(v==null||v==='')return null; let s=String(v).trim();
  if(/^\d{4}-\d{2}-\d{2}/.test(s))return goodYear(s.slice(0,10));
  const n=Number(s); if(!isNaN(n)&&n>20000&&n<80000){return goodYear(new Date(Date.UTC(1899,11,30)+n*86400000).toISOString().slice(0,10));}
  const m=s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if(m){ let a=+m[1], b=+m[2], y=+m[3]; if(y<100)y+=2000; let day,mon;
    if(a>12){day=a;mon=b;} else if(b>12){day=b;mon=a;} else {day=a;mon=b;}
    const dt=new Date(Date.UTC(y,mon-1,day)); return isNaN(dt.getTime())?null:goodYear(dt.toISOString().slice(0,10)); }
  const dd=new Date(s); return isNaN(dd.getTime())?null:goodYear(dd.toISOString().slice(0,10)); }

function normalizeRow(row, sheetName) {
  function getValue(keys) {
    for (const key of keys) {
      if (row[key] !== undefined && row[key] !== null && row[key] !== '') {
        return row[key];
      }
      for (const colName of Object.keys(row)) {
        if (colName.toLowerCase() === key.toLowerCase()) {
          if (row[colName] !== undefined && row[colName] !== null && row[colName] !== '') {
            return row[colName];
          }
        }
      }
    }
    return null;
  }

  let dateVal = null;
  const dateKeys = ['Enter Date', 'Date', 'enter date', 'A'];
  for (const key of dateKeys) {
    const val = getValue([key]);
    if (val) { dateVal = val; break; }
  }

  let subcounty = getValue(['SubCounty', 'Subcounty', 'subcounty', 'B']) || '';
  let ward = getValue(['Choose your ward', 'Ward', 'ward', 'C']) || '';
  let staff = getValue(['Number of staff deployed', 'Staff Deployed', 'staff_deployed', 'D']);
  if (staff && typeof staff === 'string') staff = num(staff);
  let location = getValue(['Indicate Road/Location/Street Name', 'Location', 'location', 'E']) || '';
  let activityType = '';
  let attendees = null;
  let partners = '';
  let keyMessages = '';
  let outputs = '';
  let outcomes = '';
  let treesPlanted = null;
  let treeType = '';
  let resourcesLacking = '';

  // ===== SHEET-SPECIFIC: Greening Initiative =====
  if (sheetName === 'Greening Initiative' || sheetName === 'Environmental Maintenance') {
    activityType = getValue([
      'Select activity category (Choose the main activity type and provide details in the relevant section.)',
      'Activity Type',
      'activity_type',
      'F'
    ]) || '';

    treesPlanted = getValue([
      'Number of trees planted (Enter the total number of seedlings planted during the activity. Only input numerical values, eg. 13)',
      'Number of trees planted',
      'Trees Planted',
      'trees_planted',
      'Tree seedlings planted',
      'Trees planted',
      'tree_planted'
    ]);
    if (treesPlanted && typeof treesPlanted === 'string') {
      treesPlanted = num(treesPlanted);
    }

    treeType = getValue([
      'Type of trees',
      'Tree Type',
      'tree_type',
      'Type of tree',
      'Species',
      'tree_species'
    ]) || '';

    const resourceKeys = [
      'Which resources are lacking? Please list the resources  needed and their quantities.  ',
      'Which resources are lacking? Please list the resources needed and their quantities.',
      'resources_lacking',
      'Resources',
      'I'
    ];
    let resources = [];
    for (const key of resourceKeys) {
      const val = getValue([key]);
      if (val && String(val).trim()) {
        resources.push(String(val).trim());
      }
    }
    resourcesLacking = resources.join(' | ');
    if (!resourcesLacking) {
      for (const colName of Object.keys(row)) {
        if (colName.toLowerCase().includes('resource') || colName.toLowerCase().includes('lack')) {
          const val = row[colName];
          if (val && String(val).trim()) {
            resourcesLacking = String(val).trim();
            break;
          }
        }
      }
    }
  }

  // ===== SHEET-SPECIFIC: Sensitization Programme =====
  if (sheetName === 'Sensitization Programme') {
    activityType = getValue([
      'Type of public sensitization activity conducted',
      'Activity Type',
      'activity_type',
      'F'
    ]) || '';

    attendees = getValue([
      'Number of attendees ',
      'Number of attendees',
      'Attendees',
      'attendees',
      'G'
    ]);
    if (attendees && typeof attendees === 'string') attendees = num(attendees);

    partners = getValue([
      'Name the partners involved in the sensitization activity',
      'Partners',
      'partners',
      'H'
    ]) || '';

    keyMessages = getValue([
      'What were the key messages pushed during the sensitization activity ',
      'What were the key messages pushed during the sensitization activity',
      'Key Messages',
      'key_messages',
      'I'
    ]) || '';

    outputs = getValue([
      'Output of the sensitization activity',
      'Outputs',
      'outputs',
      'J'
    ]) || '';

    outcomes = getValue([
      'Outcomes of the sensitization activity',
      'Outcomes',
      'outcomes',
      'K'
    ]) || '';

    const resourceKeys = [
      'Which resources are lacking? Please list the resources needed and their quantities.',
      'resources_lacking',
      'Resources'
    ];
    let resources = [];
    for (const key of resourceKeys) {
      const val = getValue([key]);
      if (val && String(val).trim()) {
        resources.push(String(val).trim());
      }
    }
    resourcesLacking = resources.join(' | ');
  }

  // ===== FALLBACK =====
  if (!activityType) {
    activityType = getValue([
      'Activity Type',
      'activity_type',
      'Type of activity'
    ]) || '';
  }

  return {
    subcounty: String(subcounty).trim(),
    ward: String(ward).trim(),
    location: String(location).trim(),
    date: iso(dateVal),
    activity_type: String(activityType).trim(),
    tree_type: String(treeType).trim(),
    staff_deployed: cl('staff_deployed', staff),
    attendees: cl('attendees', attendees),
    trees_planted: cl('trees_planted', treesPlanted),
    resources_lacking: resourcesLacking,
    partners: String(partners).trim(),
    key_messages: String(keyMessages).trim(),
    outputs: String(outputs).trim(),
    outcomes: String(outcomes).trim(),
    sheet: sheetName || 'Greening Initiative',
    _original: row
  };
}

// ================= LOAD DATA =================
let allRows = [];
let usedSource = 'none';
let sheetName = '';

const targetSheet = base.detectedSheet || 'Greening Initiative';
console.log('Target Sheet:', targetSheet);

if (targetSheet === 'Sensitization Programme') {
  try {
    const spData = $('5c. Sensitization Programs ').all().map(i => i.json);
    if (spData && spData.length > 0) {
      allRows = spData.map(row => normalizeRow(row, 'Sensitization Programme'));
      sheetName = 'Sensitization Programme';
      usedSource = 'google sheets (5c. Sensitization Programs)';
    }
  } catch(e) { 
    console.log('Could not load Sensitization Programme sheet:', e.message);
  }
} else {
  try {
    const giData = $('5a. Greening Initiatives').all().map(i => i.json);
    if (giData && giData.length > 0) {
      allRows = giData.map(row => normalizeRow(row, 'Greening Initiative'));
      sheetName = 'Greening Initiative';
      usedSource = 'google sheets (5a. Greening Initiatives)';
    }
  } catch(e) { 
    console.log('Could not load Greening Initiative sheet:', e.message);
  }
}

if (allRows.length === 0) {
  try {
    const otherData = $('5b. Env. Maintenance by Ward').all().map(i => i.json);
    if (otherData && otherData.length > 0) {
      allRows = otherData.map(row => normalizeRow(row, 'Environmental Maintenance'));
      usedSource = 'google sheets (5b. Env. Maintenance)';
      sheetName = 'Environmental Maintenance';
    }
  } catch(e) { 
    console.log('Could not load fallback sheet:', e.message);
  }
}

if (allRows.length === 0) {
  try {
    const wasteData = $('5d. Wasteload collection').all().map(i => i.json);
    if (wasteData && wasteData.length > 0) {
      allRows = wasteData.map(row => normalizeRow(row, 'Wasteload Collection'));
      usedSource = 'google sheets (5d. Wasteload)';
      sheetName = 'Wasteload Collection';
    }
  } catch(e) { 
    console.log('Could not load waste sheet:', e.message);
  }
}

console.log('Total rows loaded:', allRows.length);
console.log('Source:', usedSource);

// ===== DEBUG =====
const rowsWithTrees = allRows.filter(r => r.trees_planted !== null && r.trees_planted !== undefined);
console.log('Rows with trees_planted values:', rowsWithTrees.length);
if (rowsWithTrees.length > 0) {
  console.log('Sample tree data:', JSON.stringify(rowsWithTrees.slice(0, 5).map(r => ({
    date: r.date,
    subcounty: r.subcounty,
    trees: r.trees_planted
  })), null, 2));
} else {
  console.log('⚠️ WARNING: No trees_planted values found in any rows!');
}

// ===== RETURN PROPERLY =====
// Return an array with one object containing all rows
return [{
  json: Object.assign({}, base, { 
    rows: allRows, 
    usedSource, 
    counts: { incoming: allRows.length },
    detectedSheet: sheetName
  })
}];

const d = $input.first().json;
const intent = d.intent;
function weekStart(isoStr){ const dt=new Date(isoStr+'T00:00:00Z'); const day=(dt.getUTCDay()+6)%7; dt.setUTCDate(dt.getUTCDate()-day); return dt.toISOString().slice(0,10); }
let rows = (d.rows || []).map(r => Object.assign({}, r, { month: r.date ? r.date.slice(0,7) : null, week: r.date ? weekStart(r.date) : null }));

const NUMERIC=['waste_loads','loads_remaining','staff_deployed','attendees','trees_planted','seedlings','bins_total','bins_emptied','trucks_allocated','arrests_total'];
const BOOLEAN=['collection_complete','factual_accurate','has_evidence','night_surveillance','arrests_made'];
const TEXTFREQ=['resources_lacking','challenges','key_messages'];
const MULTI=['greening_activity','sensitization_type','tree_type','incident_category','environmental_activity','vehicle_type','waste_responsible','partners','resources_lacking','challenges'];

const metric = intent.metric || 'waste_loads';
let op = intent.operation || 'rank';
let groupBy = (intent.groupBy===undefined) ? 'subcounty' : intent.groupBy;
if (['rank','sum','avg','min','max','count','rate','difference'].includes(op) && !groupBy) groupBy='subcounty';

// ---- filters ----
let filtered = rows;
if (intent.dateFrom) filtered = filtered.filter(r=>r.date && r.date>=intent.dateFrom);
if (intent.dateTo)   filtered = filtered.filter(r=>r.date && r.date<=intent.dateTo);
for (const f of (intent.filters||[])){
  const fld=f.field, val=String(f.value||'').toLowerCase().trim();
  if(!fld||!val) continue;
  // Nairobi's admin hierarchy means a place name tagged as 'ward' by the interpreter might actually
  // be a subcounty name (e.g. 'Westlands' is a subcounty, not a ward -- its wards are Kitisuru,
  // Parklands/Highridge, Karura, Kangemi, Mountain View), or vice versa. Check both geography
  // fields together so a correct place name isn't dropped just because it landed in the 'wrong' field.
  if (fld==='ward' || fld==='subcounty'){
    filtered = filtered.filter(r => String(r.ward||'').toLowerCase().includes(val) || String(r.subcounty||'').toLowerCase().includes(val));
  } else {
    filtered = filtered.filter(r => String(r[fld]||'').toLowerCase().includes(val));
  }
}

function metricValue(r){ if(metric==='reports')return 1; if(NUMERIC.includes(metric))return r[metric]||0; if(BOOLEAN.includes(metric))return r[metric]?1:0; return 0; }
function tokens(v){ return String(v||'').split(/\s*[|,;\n]\s*/).map(x=>x.trim()).filter(Boolean); }
function keysFor(r, dim){ if(!dim) return ['All']; if(MULTI.includes(dim)){ const t=tokens(r[dim]); return t.length?t:['(none)']; } return [String(r[dim]||'(none)').trim()||'(none)']; }

const math = { metric, operation:op, groupBy, field:metric, recordCount:filtered.length, dataSource:d.usedSource,
  period:{ from:intent.dateFrom||null, to:intent.dateTo||null, label:intent.periodLabel||'all dates' }, pre_computed:true };

// ---------- TEXT-FREQUENCY breakdown ----------
if (op==='breakdown' && TEXTFREQ.includes(metric) && !groupBy){
  const freq={}; for(const r of filtered){ for(const t of tokens(r[metric])){ const k=t; freq[k]=(freq[k]||0)+1; } }
  let arr=Object.entries(freq).map(([group,value])=>({group,value})).sort((a,b)=>b.value-a.value);
  math.dimension=metric; math.valueBasis='mentions'; math.breakdown=arr.slice(0,intent.limit||15);
  math.total=filtered.length; math.primary=arr[0]?{label:arr[0].group,value:arr[0].value}:null;
}
// ---------- DISTRIBUTION / BREAKDOWN across a dimension ----------
else if (op==='breakdown' || intent.type==='distribution'){
  const dim=groupBy||'subcounty'; const useNumeric=NUMERIC.includes(metric);
  const g={}; for(const r of filtered){ for(const k of keysFor(r,dim)){ g[k]=g[k]||{v:0,n:0}; g[k].v+= useNumeric?(r[metric]||0):1; g[k].n++; } }
  let arr=Object.entries(g).map(([group,o])=>({group, value:o.v, records:o.n})).filter(x=>x.group&&x.group!=='(none)');
  arr.sort((a,b)=> intent.order==='asc'? a.value-b.value : b.value-a.value);
  math.dimension=dim; math.valueBasis=useNumeric?metric:'record count';
  math.breakdown=arr.slice(0,intent.limit||15); math.total=arr.reduce((s,x)=>s+x.value,0);
  math.primary=arr[0]?{label:arr[0].group,value:arr[0].value}:null;
}
// ---------- RATE (boolean %) ----------
else if (op==='rate'){
  const bm=BOOLEAN.includes(metric)?metric:'collection_complete';
  // denominator = records where the flag is applicable (e.g. completion only counts waste-collection records)
  let applicable=filtered;
  if(bm==='collection_complete') applicable=filtered.filter(r=>String(r.collection_status||'').trim()!=='');
  const trueN=applicable.filter(r=>r[bm]).length;
  math.metric=bm; math.applicableRecords=applicable.length; math.trueCount=trueN;
  math.rate=applicable.length?trueN/applicable.length:0; math.ratePct=applicable.length?Math.round(math.rate*1000)/10:null;
  const g={}; for(const r of applicable){ for(const k of keysFor(r,groupBy)){ g[k]=g[k]||{t:0,n:0}; g[k].t+=r[bm]?1:0; g[k].n++; } }
  let arr=Object.entries(g).map(([group,o])=>({group, ratePct:o.n?Math.round(o.t/o.n*1000)/10:0, n:o.n})).filter(x=>x.group&&x.group!=='(none)');
  arr.sort((a,b)=>b.ratePct-a.ratePct); math.byGroup=arr.slice(0,15);
  math.primary={label:bm+' rate', value:(math.ratePct!=null?math.ratePct+'%':'n/a')};
}
// ---------- RATIO (metric / secondaryMetric) ----------
else if (op==='ratio' || intent.type==='ratio'){
  const a=metric, b=intent.secondaryMetric||'bins_total';
  const sA=filtered.reduce((s,r)=>s+(r[a]||0),0), sB=filtered.reduce((s,r)=>s+(r[b]||0),0);
  math.numeratorMetric=a; math.denominatorMetric=b; math.numerator=sA; math.denominator=sB;
  math.ratio=sB?sA/sB:null; math.ratioPct=sB?Math.round(sA/sB*1000)/10:null;
  math.primary={label:a+' / '+b, value:(math.ratioPct!=null?math.ratioPct+'%':'n/a')};
}
// ---------- TREND (by day / week / month) ----------
else if (op==='trend' || intent.type==='trend'){
  const gran = intent.granularity || 'month';
  const bucketOf = r => gran==='day' ? r.date : gran==='week' ? r.week : r.month;
  const g={}; for(const r of filtered){ const k=bucketOf(r); if(!k)continue; g[k]=(g[k]||0)+metricValue(r); }
  const t=Object.entries(g).sort().map(([bucket,total])=>({bucket,total})); math.trend=t; math.granularity=gran;
  if(t.length){ math.primary={label:t[t.length-1].bucket, value:t[t.length-1].total};
    if(t.length>=2){ const f=t[0].total,l=t[t.length-1].total; math.change=l-f; math.changePct=f?Math.round((l-f)/f*1000)/10:null; math.firstBucket=t[0].bucket; math.lastBucket=t[t.length-1].bucket; } }
  else math.primary=null;
}
// ---------- DIFFERENCE (compare named groups) ----------
else if (op==='difference' || intent.type==='comparison'){
