  let arr=Object.entries(g).map(([group,o])=>({group,total:o.v,records:o.n})).filter(x=>x.group&&x.group!=='(none)').sort((a,b)=>b.total-a.total);
  const targets=(intent.filters||[]).filter(f=>f.field===dim).map(f=>String(f.value||'').toLowerCase());
  const comp = targets.length ? arr.filter(x=>targets.some(t=>x.group.toLowerCase().includes(t))) : arr.slice(0,2);
  math.comparison=comp; math.ranking=arr.slice(0,10);
  math.difference = comp.length>=2 ? Math.abs(comp[0].total-comp[1].total) : null;
  math.primary = comp.length>=2 ? {label:'gap '+comp[0].group+' vs '+comp[1].group, value:math.difference} : (arr[0]?{label:arr[0].group,value:arr[0].total}:null);
}
// ---------- AGGREGATION: rank / sum / avg / count / min / max ----------
else {
  const g={};
  for(const r of filtered){ for(const k of keysFor(r,groupBy)){ if(!g[k])g[k]={sum:0,n:0,vals:[]}; const v=metricValue(r); g[k].sum+=v; g[k].n++; if(metric==='reports'||r[metric]!=null)g[k].vals.push(v);} }
  let arr=Object.entries(g).map(([group,o])=>({group, total:o.sum, average:o.vals.length?Math.round(o.sum/o.vals.length*100)/100:0, records:o.n, min:o.vals.length?Math.min.apply(null,o.vals):null, max:o.vals.length?Math.max.apply(null,o.vals):null}));
  arr=arr.filter(x=>x.group&&x.group!=='(none)');
  const key = op==='avg'?'average':op==='min'?'min':op==='max'?'max':op==='count'?'records':'total';
  arr.sort((a,b)=> intent.order==='asc'?(a[key]-b[key]):(b[key]-a[key]));
  math.ranking=arr.slice(0,intent.limit||10);
  math.grandTotal=arr.reduce((s,x)=>s+x.total,0);
  math.top=arr[0]||null;
  math.primary = math.top ? {label: math.top.group + (op==='avg'?' (avg)':op==='count'?' (records)':''), value: math.top[key]} : null;
}

