// ================= CHART CONFIGURATION =================
let chartUrl = null;
let chartData = null;

// Function to generate QuickChart URL
function generateChartURL(config) {
    const baseUrl = 'https://quickchart.io/chart';
    const encoded = encodeURIComponent(JSON.stringify(config));
    return `${baseUrl}?c=${encoded}`;
}

// Function to detect what type of chart to generate
function detectChartType(mathData, question) {
    const q = question.toLowerCase();

    // Check if we have ranking data (bar chart)
    if (mathData.ranking && mathData.ranking.length > 0) {
        return {
            type: 'bar',
            title: detectChartTitle(mathData, q),
            data: mathData.ranking
        };
    }

    // Check if we have breakdown data (bar chart)
    if (mathData.breakdown && mathData.breakdown.length > 0) {
        return {
            type: 'bar',
            title: detectChartTitle(mathData, q),
            data: mathData.breakdown
        };
    }

    // Check if we have trend data (line chart)
    if (mathData.trend && mathData.trend.length > 0) {
        return {
            type: 'line',
            title: detectChartTitle(mathData, q),
            data: mathData.trend
        };
    }

    // Check if we have comparison data (bar chart)
    if (mathData.comparison && mathData.comparison.length > 0) {
        return {
            type: 'bar',
            title: detectChartTitle(mathData, q),
            data: mathData.comparison
        };
    }

    return null;
}

function detectChartTitle(mathData, question) {
    const q = question.toLowerCase();
    let title = 'Green & Clean Nairobi Data';

    // Extract what the chart is showing
    if (mathData.metric) {
        const metricLabels = {
            'waste_loads': 'Waste Loads',
            'staff_deployed': 'Staff Deployed',
            'attendees': 'Attendees',
            'trees_planted': 'Trees Planted',
            'reports': 'Activity Count',
            'resources_lacking': 'Most Lacking Resources',
            'key_messages': 'Key Sensitization Messages',
            'partners': 'Sensitization Partners',
            'outputs': 'Sensitization Outputs',
            'outcomes': 'Sensitization Outcomes',
            'activity_type': 'Activity Types'
        };
        const label = metricLabels[mathData.metric] || mathData.metric.replace(/_/g, ' ');
        title = `${label} by ${mathData.groupBy || 'Category'}`;
    }

    // Add time period if available
    if (mathData.period && mathData.period.label && mathData.period.label !== 'all dates') {
        title += ` (${mathData.period.label})`;
    }

    return title;
}

// Function to build Chart.js config
function buildChartConfig(chartInfo) {
    if (!chartInfo || !chartInfo.data || chartInfo.data.length === 0) {
        return null;
    }

    const data = chartInfo.data;
    let labels = [];
    let values = [];
    let datasetLabel = '';

    // Extract labels and values based on data structure
    if (data[0].group !== undefined) {
        // Ranking or breakdown data
        labels = data.map(item => item.group);
        values = data.map(item => item.value || item.total || 0);
        datasetLabel = chartInfo.title || 'Value';
    } else if (data[0].bucket !== undefined) {
        // Trend data (time series)
        labels = data.map(item => item.bucket);
        values = data.map(item => item.total || 0);
        datasetLabel = chartInfo.title || 'Trend';
    } else if (data[0].label !== undefined) {
        // Generic data
        labels = data.map(item => item.label);
        values = data.map(item => item.value || 0);
        datasetLabel = chartInfo.title || 'Value';
    } else {
        // Fallback - use keys as labels
        labels = Object.keys(data);
        values = Object.values(data);
        datasetLabel = chartInfo.title || 'Value';
    }

    // Determine colors
    const colors = [
        '#3498db', '#e74c3c', '#2ecc71', '#f39c12', 
        '#9b59b6', '#1abc9c', '#e67e22', '#34495e',
        '#27ae60', '#2980b9', '#8e44ad', '#16a085'
    ];

    const backgroundColor = values.map((_, i) => colors[i % colors.length]);

    const config = {
        type: chartInfo.type || 'bar',
        data: {
            labels: labels,
            datasets: [{
                label: datasetLabel,
                data: values,
                backgroundColor: backgroundColor,
                borderColor: colors.map(c => c),
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: true,
            plugins: {
                title: {
                    display: true,
                    text: chartInfo.title || 'Green & Clean Nairobi Analysis',
                    font: {
                        size: 16,
                        weight: 'bold'
                    }
                },
                legend: {
                    display: true,
                    position: 'top'
                }
            },
            scales: {
                y: {
                    beginAtZero: true,
                    ticks: {
                        callback: function(value) {
                            if (value >= 1000) {
                                return value.toLocaleString();
                            }
                            return value;
                        }
                    }
                }
            }
        }
    };

    // Customize for line charts
    if (chartInfo.type === 'line') {
        config.options.elements = {
            line: {
                tension: 0.3 // Smooth lines
            }
        };
        config.data.datasets[0].backgroundColor = 'rgba(52, 152, 219, 0.1)';
        config.data.datasets[0].borderColor = '#3498db';
        config.data.datasets[0].pointBackgroundColor = '#3498db';
        config.data.datasets[0].fill = true;
        config.data.datasets[0].pointRadius = 4;
    }

    // Customize for pie/doughnut charts
    if (chartInfo.type === 'pie' || chartInfo.type === 'doughnut') {
        delete config.options.scales;
        config.options.plugins.legend.position = 'right';
    }

    return config;
}

